Write a program in C to implement push, pop and display operations for stacks using arrays. (7 Marks)
Model Answer:
#define MAX 5
int stack[MAX], top = -1;
void push(int val) {
    if (top == MAX - 1) { printf("Stack Overflow\n"); return; }
    stack[++top] = val;
}
int pop() {
    if (top == -1) { printf("Stack Underflow\n"); return -1; }
    return stack[top--];
}
void display() {
    if (top == -1) { printf("Stack Empty\n"); return; }
    for(int i = top; i >= 0; i--) printf("%d ", stack[i]);
    printf("\n");
}

Write functions in C for the following operations without using built-in functions: i) Compare two strings. ii) Concatenate two strings. iii) Reverse a string (8 Marks)
Model Answer:
i) Compare:
int strCompare(char s1[], char s2[]) {
    int i = 0;
    while(s1[i] == s2[i]) {
        if(s1[i] == '\0') return 0;
        i++;
    }
    return s1[i] - s2[i];
}
ii) Concatenate:
void strConcat(char dest[], char src[]) {
    int i = 0, j = 0;
    while(dest[i] != '\0') i++;
    while(src[j] != '\0') { dest[i++] = src[j++]; }
    dest[i] = '\0';
}
iii) Reverse:
void strReverse(char str[]) {
    int len = 0, i;
    while(str[len] != '\0') len++;
    for(i = 0; i < len/2; i++) {
        char temp = str[i];
        str[i] = str[len - 1 - i];
        str[len - 1 - i] = temp;
    }
}

Develop a C program to implement insertion, deletion and display operations on Linear queue. (10 Marks)
Model Answer:
#define MAX 5
int queue[MAX], front = -1, rear = -1;
void insert(int val) {
    if (rear == MAX - 1) { printf("Queue Overflow\n"); return; }
    if (front == -1) front = 0;
    queue[++rear] = val;
}
void delete() {
    if (front == -1 || front > rear) { printf("Queue Underflow\n"); return; }
    printf("Deleted: %d\n", queue[front++]);
}
void display() {
    if (front == -1 || front > rear) { printf("Queue Empty\n"); return; }
    for(int i = front; i <= rear; i++) printf("%d ", queue[i]);
    printf("\n");
}

Write a program in C to implement a stack of integers using a singly linked list. (10 Marks)
