struct Node {
    int data;
    struct Node* next;
} *top = NULL;
void push(int val) {
    struct Node* temp = (struct Node*)malloc(sizeof(struct Node));
    temp->data = val;
    temp->next = top;
    top = temp;
}
void pop() {
    if(top == NULL) { printf("Stack Underflow\n"); return; }
    struct Node* temp = top;
    printf("Popped: %d\n", top->data);
    top = top->next;
    free(temp);
}

